package com.nigson.commerce.pricing;
import java.util.*;
import java.math.*;
import java.time.Instant;
import java.sql.Timestamp;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import com.nigson.commerce.market.MarketValues;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
/** Current explicit assignment wins; an invalid organization assignment never falls back to retail. */
public final class JdbcPricing implements Pricing {
 private final JdbcTemplate jdbc;private final int phase;public JdbcPricing(JdbcTemplate jdbc,int phase){this.jdbc=jdbc;this.phase=phase;}
 private record Sku(UUID product,int scale,BigDecimal pack){}
 private record Market(UUID retail,String currency,int scale){}
 public Resolved resolve(UUID sku,BigDecimal quantity,UUID market,UUID organization,Instant now,Instant maximumValidity,boolean lock){if(!TransactionSynchronizationManager.isActualTransactionActive())throw new IllegalStateException("LOCAL_TRANSACTION_REQUIRED");if(quantity==null||now==null||maximumValidity==null||!maximumValidity.isAfter(now))throw PricingValues.rule();var skus=jdbc.query("SELECT s.product_id,s.quantity_scale,s.pack_size FROM commerce.sku s JOIN commerce.product p ON p.id=s.product_id WHERE s.id=? AND s.active AND s.deleted_at IS NULL AND p.status='ACTIVE' AND p.deleted_at IS NULL"+(lock?" FOR SHARE OF p,s":""),(r,n)->new Sku(r.getObject(1,UUID.class),r.getInt(2),r.getBigDecimal(3)),sku);if(skus.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);var item=skus.getFirst();PricingValues.quantity(PricingValues.decimal(quantity),item.scale());var markets=jdbc.query("SELECT m.retail_price_book_id,m.currency_code,c.minor_unit FROM commerce.market m JOIN commerce.currency c ON c.code=m.currency_code JOIN commerce.product_market_eligibility e ON e.market_id=m.id WHERE m.id=? AND m.code='NG' AND m.enabled AND m.returns_policy_revision IS NOT NULL AND length(trim(m.returns_policy_revision))>0 AND c.active AND c.code='NGN' AND c.minor_unit=2 AND e.product_id=? AND e.eligible"+(lock?" FOR SHARE OF m,c,e":""),(r,n)->new Market(r.getObject(1,UUID.class),r.getString(2),r.getInt(3)),market,item.product());if(markets.size()!=1)throw PricingValues.rule();var policy=jdbc.queryForObject("SELECT tax_policy::text FROM commerce.market WHERE id=?",String.class,market);try{MarketValues.tax(EventCodec.JSON.readTree(policy));}catch(Problem.Failure invalid){throw PricingValues.rule();}var m=markets.getFirst();var context=EventCodec.JSON.createObjectNode();UUID book=m.retail();String segment="RETAIL";BigDecimal pack=item.pack(),minimum=BigDecimal.ZERO,minimumOrder=BigDecimal.ZERO;if(organization!=null){if(phase<3)throw new Problem.Failure(ProblemCode.ACCESS_DENIED);var assignments=jdbc.query("SELECT price_book_id,id,version FROM commerce.price_assignment WHERE organization_id=? AND market_id=? AND active"+(lock?" FOR SHARE":""),(r,n)->new Object[]{r.getObject(1,UUID.class),r.getObject(2,UUID.class),r.getLong(3)},organization,market);if(assignments.size()!=1)throw PricingValues.rule();book=(UUID)assignments.getFirst()[0];context.put("priceAssignmentId",assignments.getFirst()[1].toString());context.put("priceAssignmentVersion",(Long)assignments.getFirst()[2]);var revisions=EventCodec.JSON.createArrayNode();context.set("wholesaleRules",revisions);segment="DISTRIBUTOR";var rules=jdbc.query("SELECT minimum_quantity,pack_multiple,minimum_order_amount,id,rule_revision,version FROM commerce.wholesale_rule WHERE market_id=? AND (organization_id IS NULL OR organization_id=?) AND (sku_id IS NULL OR sku_id=?) ORDER BY id LIMIT 501"+(lock?" FOR SHARE":""),(r,n)->{var revision=EventCodec.JSON.createObjectNode();revision.put("id",r.getObject(4,UUID.class).toString());revision.put("revision",r.getLong(5));revision.put("version",r.getLong(6));revisions.add(revision);return new BigDecimal[]{r.getBigDecimal(1),r.getBigDecimal(2),r.getBigDecimal(3)};},market,organization,sku);if(rules.size()>500)throw PricingValues.rule();for(var rule:rules){if(rule[0]!=null)minimum=minimum.max(PricingValues.quantity(PricingValues.decimal(rule[0]),item.scale()));if(rule[1]!=null)pack=lcm(pack,PricingValues.quantity(PricingValues.decimal(rule[1]),item.scale()),item.scale());if(rule[2]!=null)minimumOrder=minimumOrder.max(PricingValues.minor(PricingValues.decimal(rule[2]),m.scale()));}}
  if(book==null||quantity.compareTo(minimum)<0||pack==null||pack.signum()<=0||quantity.remainder(pack).signum()!=0)throw PricingValues.rule();var books=jdbc.query("SELECT revision,effective_until FROM commerce.price_book WHERE id=? AND active AND currency_code=? AND segment=? AND effective_from<=? AND (effective_until IS NULL OR effective_until>?)"+(lock?" FOR SHARE":""),(r,n)->Map.entry(r.getLong(1),r.getTimestamp(2)==null?maximumValidity:r.getTimestamp(2).toInstant()),book,m.currency(),segment,Timestamp.from(now),Timestamp.from(now));if(books.size()!=1)throw PricingValues.rule();var tiers=jdbc.query("SELECT minimum_quantity,unit_amount FROM commerce.price_entry WHERE price_book_id=? AND sku_id=? AND minimum_quantity<=? ORDER BY minimum_quantity DESC LIMIT 1"+(lock?" FOR SHARE":""),(r,n)->Map.entry(r.getBigDecimal(1),r.getBigDecimal(2)),book,sku,quantity);if(tiers.size()!=1)throw PricingValues.rule();var tier=tiers.getFirst();minimum=minimum.max(tier.getKey());PricingValues.quantity(PricingValues.decimal(minimum),item.scale());BigDecimal amount=PricingValues.minor(PricingValues.decimal(tier.getValue()),m.scale());Instant until=books.getFirst().getValue().isBefore(maximumValidity)?books.getFirst().getValue():maximumValidity;return new Resolved(sku,item.product(),book,books.getFirst().getKey(),quantity,amount,minimum,pack,minimumOrder,until,context);
 }
 private static BigDecimal lcm(BigDecimal one,BigDecimal two,int scale){BigInteger a=one.movePointRight(scale).toBigIntegerExact(),b=two.movePointRight(scale).toBigIntegerExact();if(a.signum()<=0||b.signum()<=0)throw PricingValues.rule();BigDecimal result=new BigDecimal(a.divide(a.gcd(b)).multiply(b),scale);if(result.precision()>20)throw PricingValues.rule();return result;}
}
